<?php use kuoto\event\Listener; use kuoto\event\player\PlayerServerSelectEvent; use kuoto\event\proxy\ProxyPingEvent; use kuoto\server\SynapseServer; class QueueListener implements Listener { private $proxy; public function __construct(SynapseServer $proxy) { $this->proxy = $proxy; } public function onPing(ProxyPingEvent $event) { $players = 0; $maxPlayers = 0; $servers = 0; foreach ($this->proxy->getManager()->getServers() as $server) { $info = $server->getInfo(); if (!is_array($info)) { continue; } $servers++; if (isset($info['playerCount'])) { $players += (int) $info['playerCount']; } if (isset($info['maxPlayers'])) { $maxPlayers += (int) $info['maxPlayers']; } } if ($servers === 0) { $event->setMotd('§l§9Genesys NETWORK §8| §7OFFLINE'); $event->setSubMotd(''); $event->setPlayerCount(0); $event->setMaxPlayers(0); return; } $event->setMotd( '§l§9Genesys NETWORK §8| §f' . $players . '/' . $maxPlayers ); $event->setSubMotd(''); $event->setPlayerCount($players); $event->setMaxPlayers($maxPlayers); } public function onServerSelect(PlayerServerSelectEvent $event) { foreach ($event->getAvailableServers() as $server) { $info = $server->getInfo(); if (!isset($info['isMainServer']) || !$info['isMainServer']) { continue; } $players = isset($info['playerCount']) ? (int) $info['playerCount'] : 0; if ($players < 39) { $event->setTargetServer($server); } return; } }}